package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** User-owned permanent downloads are outside the streaming cache. Queue runs only on Home. */
final class OfflineDownloads {
 private static OfflineDownloads singleton;static synchronized OfflineDownloads get(Context c){if(singleton==null)singleton=new OfflineDownloads(c.getApplicationContext());return singleton;}
 final Context c;final SharedPreferences prefs;final File folder;final ExecutorService executor=Executors.newSingleThreadExecutor();volatile boolean visible,running;volatile String active="";final Set<String> cancelled=ConcurrentHashMap.newKeySet();
 OfflineDownloads(Context context){c=context;prefs=c.getSharedPreferences("tv-downloads",0);folder=new File(c.getFilesDir(),"offline-videos");folder.mkdirs();}
 synchronized void add(Movie movie){if(!movie.saveAllowed){toast("This chat does not allow saving media");return;}if(movie.fileId<=0){toast("Already a local video");return;}String id=MediaCache.key(movie.cacheIdentity());if(active.equals(id)){toast("Download is already running");return;}if(prefs.contains("ready:"+id)){toast("Already downloaded");return;}cancelled.remove(id);prefs.edit().putString("queue:"+id,movie.json().toString()).putString("status:"+id,"Queued · runs while Home is visible").apply();toast("Added to downloads");start();}
 synchronized void visibility(boolean on){visible=on;if(on)start();}
 synchronized void start(){if(running||!visible)return;running=true;executor.execute(()->{try{for(Map.Entry<String,?> e:prefs.getAll().entrySet()){if(!visible)break;if(!e.getKey().startsWith("queue:")||!(e.getValue() instanceof String))continue;String id=e.getKey().substring(6);active=id;try{download(id,Movie.from(new JSONObject((String)e.getValue())));}catch(Exception error){prefs.edit().putString("status:"+id,"Paused / failed: "+(error.getMessage()==null?error.getClass().getSimpleName():error.getMessage())+" · choose Retry").apply();}finally{active="";}}}finally{running=false;boolean queued=false;for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("queue:")&&prefs.getString("status:"+e.getKey().substring(6),"").startsWith("Queued")){queued=true;break;}if(queued&&visible)start();}});}
 void download(String id,Movie movie)throws Exception {if(cancelled.contains(id))return;File partial=new File(folder,id+".partial"),dest=new File(folder,id+".video");if(movie.size<=0)throw new IOException("Video size is unknown");long free=folder.getUsableSpace();if(free<movie.size*2+64L*1024*1024)throw new IOException("Need "+MainActivity.size(movie.size*2+64L*1024*1024)+" free");TelegramBridge tg=TelegramBridge.getInstance(c);if(!tg.ready)throw new IOException("Telegram is not connected");ChannelSession session=ChannelSession.get(c);if(session.playbackVisible)return;session.closeStore();tg.download(movie.fileId,0,0,4);long lastBytes=-1,lastProgress=SystemClock.elapsedRealtime();
  try{while(visible&&!cancelled.contains(id)&&!session.playbackVisible){Object file=tg.waitRequest("GetFile","fileId",movie.fileId),local=TelegramBridge.get(file,"local");long bytes=TelegramBridge.num(local,"downloadedSize");if(bytes>lastBytes){lastBytes=bytes;lastProgress=SystemClock.elapsedRealtime();}prefs.edit().putString("status:"+id,String.format(Locale.US,"Downloading %d%% · %s / %s",Math.min(99,bytes*100/movie.size),MainActivity.size(bytes),MainActivity.size(movie.size))).apply();if(TelegramBridge.bool(local,"isDownloadingCompleted")){File original=new File(TelegramBridge.str(local,"path"));if(!original.isFile()||original.length()!=movie.size)throw new IOException("Downloaded file is incomplete");try(InputStream in=new FileInputStream(original);OutputStream out=new FileOutputStream(partial)){byte[] buffer=new byte[262144];int n;while((n=in.read(buffer))>=0){if(cancelled.contains(id)||!visible)throw new IOException("Cancelled or app left Home");out.write(buffer,0,n);}}if(partial.length()!=movie.size||!partial.renameTo(dest))throw new IOException("Cannot save download");prefs.edit().putString("ready:"+id,movie.json().toString()).remove("queue:"+id).putString("status:"+id,"Ready offline · "+MainActivity.size(movie.size)).apply();toast("Offline download ready");return;}if(SystemClock.elapsedRealtime()-lastProgress>120000)throw new IOException("No download progress for 2 minutes");Thread.sleep(1000);}
   prefs.edit().putString("status:"+id,"Paused · return Home and choose Retry").apply();
  }finally{partial.delete();if(!session.playbackVisible)tg.cancel(movie.fileId);}
 }
 void show(MainActivity a){List<String> ids=new ArrayList<>();List<Movie> movies=new ArrayList<>();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if((e.getKey().startsWith("ready:")||e.getKey().startsWith("queue:"))&&e.getValue() instanceof String)try{String id=e.getKey().substring(6);if(!ids.contains(id)){ids.add(id);movies.add(Movie.from(new JSONObject((String)e.getValue())));}}catch(Exception ignored){}if(ids.isEmpty()){Ui.message(a,"Offline downloads","Hold OK on a movie → Download for offline. Downloads run while the Home screen is visible; playback takes priority.");return;}String[] names=new String[ids.size()+1];names[0]="Retry queued downloads / refresh status";for(int i=0;i<ids.size();i++)names[i+1]=MediaTitle.parse(movies.get(i).title).display()+"\n"+prefs.getString("status:"+ids.get(i),"Queued");Ui.menu(a,"Offline downloads",names,n->{if(n==0){start();show(a);return;}String id=ids.get(n-1);Movie m=movies.get(n-1);boolean ready=prefs.contains("ready:"+id)&&new File(folder,id+".video").isFile();Ui.menu(a,"Download",ready?new String[]{"Play offline","Delete download"}:new String[]{"Retry","Cancel download"},x->{if(x==0){if(ready){Movie local=Movie.from(m.json());local.fileId=0;local.uri=Uri.fromFile(new File(folder,id+".video")).toString();a.session.selectMovie(local);a.previewMovie=local;a.play(Collections.singletonList(local),0,false);}else start();}else Ui.dialog(a).setTitle("Remove this download?").setMessage("Removes this app's offline copy or cancels the queued download. The Telegram original stays.").setPositiveButton("Remove",(d,w)->{cancelled.add(id);new File(folder,id+".video").delete();prefs.edit().remove("queue:"+id).remove("ready:"+id).remove("status:"+id).apply();}).setNegativeButton("Keep",null).show();});});}
 void external(Activity activity,Movie movie){String id=MediaCache.key(movie.cacheIdentity());File file=new File(folder,id+".video");if(!movie.saveAllowed||!prefs.contains("ready:"+id)||!file.isFile()){toast("Download this video first to open it in another player");return;}try{Uri uri=Uri.parse("content://"+c.getPackageName()+".offline/"+id+".video");activity.startActivity(Intent.createChooser(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"video/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Open offline video"));}catch(Exception e){toast("No external video player is available");}}
 void toast(String text){new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(c,text,android.widget.Toast.LENGTH_SHORT).show());}
}
